#include <iostream>
#include <stdexcept>

class Time {
public:
    explicit Time(int h = 0, int m = 0, int s = 0) {
        setTime(h, m, s);
    }

    void setTime(int h, int m, int s) {
        if (h >= 0 && h < 24 && m >= 0 && m < 60 && s >= 0 && s < 60) {
            hour = static_cast<unsigned int>(h);
            minute = static_cast<unsigned int>(m);
            second = static_cast<unsigned int>(s);
        } else {
            throw std::invalid_argument("hour, minute and/or second was out of range");
        }
    }

    unsigned int getHour() const { return hour; }

    // Dangerous: returns reference to private data member
    unsigned int& badSetHour(int hh) {
        if (hh >= 0 && hh < 24) {
            hour = static_cast<unsigned int>(hh);
        } else {
            throw std::invalid_argument("hour must be 0-23");
        }
        return hour;
    }

private:
    unsigned int hour{0};
    unsigned int minute{0};
    unsigned int second{0};
};

int main() {
    Time t;

    // Alias binds directly to private data member 'hour'
    unsigned int& hourRef = t.badSetHour(20);
    std::cout << "Valid hour before modification: " << hourRef << '\n';

    hourRef = 30; // Bypasses validation!
    std::cout << "Invalid hour after modification: " << t.getHour() << '\n';

    // Function call used directly as an lvalue
    t.badSetHour(12) = 74;
    std::cout << "Function call as lvalue, invalid hour: " << t.getHour() << '\n';

    return 0;
}

#include <iostream>

class Date {
public:
    explicit Date(int m = 1, int d = 1, int y = 2000)
        : month(m), day(d), year(y) {}

    void print() const {
        std::cout << month << '/' << day << '/' << year;
    }

private:
    unsigned int month{1};
    unsigned int day{1};
    unsigned int year{2000};
};

int main() {
    Date date1(7, 4, 2004);
    Date date2; // Defaults to 1/1/2000

    std::cout << "date1 = ";
    date1.print();
    std::cout << "\ndate2 = ";
    date2.print();

    // Default memberwise assignment
    date2 = date1;

    std::cout << "\n\nAfter default memberwise assignment, date2 = ";
    date2.print();
    std::cout << '\n';

    return 0;
}
